(function($){'use strict';const Validation={init:function(){this.requiredFields();this.emailValidation();this.passwordValidation();this.numericValidation();this.lengthValidation();this.patternValidation();this.urlValidation();this.phoneValidation();this.clearValidation();},requiredFields:function(){$(document).on('submit','form',function(e){let valid=true;$(this).find('[required]').each(function(){const value=$.trim($(this).val());if(value===''){Validation.invalidate($(this),'This field is required.');valid=false;}else{Validation.validate($(this));}});if(!valid){e.preventDefault();}});},emailValidation:function(){const regex=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;$(document).on('input blur','input[type="email"]',function(){const value=$.trim($(this).val());if(value===''){return;}
if(!regex.test(value)){Validation.invalidate($(this),'Enter a valid email address.');}else{Validation.validate($(this));}});},passwordValidation:function(){$(document).on('input','input[name="confirm_password"]',function(){const password=$('input[name="password"]').val();if($(this).val()!==password){Validation.invalidate($(this),'Passwords do not match.');}else{Validation.validate($(this));}});},numericValidation:function(){$(document).on('input','input[data-numeric]',function(){this.value=this.value.replace(/[^0-9]/g,'');});},lengthValidation:function(){$(document).on('input','input[minlength],textarea[minlength],input[maxlength],textarea[maxlength]',function(){const value=$(this).val();const min=parseInt($(this).attr('minlength'),10);const max=parseInt($(this).attr('maxlength'),10);if(!isNaN(min)&&value.length<min){Validation.invalidate($(this),'Minimum '+min+' characters required.');return;}
if(!isNaN(max)&&value.length>max){Validation.invalidate($(this),'Maximum '+max+' characters allowed.');return;}
Validation.validate($(this));});},patternValidation:function(){$(document).on('blur','input[pattern]',function(){const pattern=new RegExp($(this).attr('pattern'));if($(this).val()&&!pattern.test($(this).val())){Validation.invalidate($(this),'Invalid format.');}else{Validation.validate($(this));}});},urlValidation:function(){const regex=/^(https?:\/\/)[^\s/$.?#].[^\s]*$/i;$(document).on('blur','input[type="url"]',function(){const value=$.trim($(this).val());if(value===''){return;}
if(!regex.test(value)){Validation.invalidate($(this),'Enter a valid URL.');}else{Validation.validate($(this));}});},phoneValidation:function(){const regex=/^[0-9+\-\s()]{7,20}$/;$(document).on('blur','input[type="tel"]',function(){const value=$.trim($(this).val());if(value===''){return;}
if(!regex.test(value)){Validation.invalidate($(this),'Enter a valid phone number.');}else{Validation.validate($(this));}});},clearValidation:function(){$(document).on('focus','input,textarea,select',function(){$(this).removeClass('nba-invalid nba-valid');$(this).next('.nba-field-error').remove();});},validate:function(field){field.removeClass('nba-invalid').addClass('nba-valid');field.next('.nba-field-error').remove();},invalidate:function(field,message){field.removeClass('nba-valid').addClass('nba-invalid');field.next('.nba-field-error').remove();$('<div class="nba-field-error"></div>').text(message).insertAfter(field);}};$(function(){Validation.init();window.NBValidation=Validation;});})(jQuery);